import sys

data = sys.stdin.read().split()
q = int(data[0])
ups = [(data[1 + 2 * i], int(data[2 + 2 * i])) for i in range(q)]
people = sorted(set(n for n, _ in ups))
final = {p: sum(s for n, s in ups if n == p) for p in people}
best = max(final.values())
first = {}
for p in people:
    if final[p] == best:
        run = 0
        for i, (n, s) in enumerate(ups):
            if n == p:
                run += s
                if run == best:
                    first[p] = i
                    break
print(min(first, key=lambda p: first[p]))

